    part def Tarot_T960_TL960A_hexa_960mm {
        doc /* source: https://tarotrc.com/Product/Detail.aspx?Id=f86fa22e-c589-41df-8c14-d9886f804a05&Lang=en retrieved 2026-07-14 */
        attribute massG : Real = 1050.0;
