    part def Multirotor_power_electronics_and_integration_budget_500g {
        doc /* source: docs/REALIZATION_DESIGN.md#integration-mass-budget retrieved 2026-07-14; conservative integration mass budget */
        attribute massG : Real = 500.0;
    }
    part realizedPropulsion : T_Motor_MN4006_KV380_P16x5_4_6S;
    part realizedPower : Tattu_Plus_16000mAh_6S_15C;
    part realizedAirframe : Tarot_T960_TL960A_hexa_960mm;
    part realizedIntegration : Multirotor_power_electronics_and_integration_budget_500g;
    requirement def REQ_PERF_002 { attribute target : Real = 25.0; }
    requirement req_perf_002 : REQ_PERF_002;
    requirement def REQ_CONS_003 { attribute target : Real = 8.0; }
    requirement req_cons_003 : REQ_CONS_003;
    calc def RealizedEndurance {
        in capacityMah : Real; in hoverCurrentA : Real; in rotorCount : Real;
        in avionicsA : Real;
        (capacityMah / 1000.0 * 0.8) / (hoverCurrentA * rotorCount + avionicsA) * 60.0
    }
    part def RealizedDesign {
        attribute realizedEnduranceMin : Real = RealizedEndurance(16000.0, 4.009009009, 6.0, 0.540540541);
        attribute realizedRangeM : Real = 0.000000000;
        attribute realizedMassKg : Real = 5.540000000;
        attribute packNominalVoltageV : Real = 22.200000000;
        attribute motorCurveVoltageV : Real = 24.000000000;
        attribute voltageRatio : Real = 0.925000000;
        attribute realizedCruiseSpeedMps : Real = 0.000000000;
        assert constraint realizationCloses1 { realizedEnduranceMin >= 25.0 }
        assert constraint realizationCloses5 { realizedMassKg <= 8.0 }
        satisfy req_perf_002;
        satisfy req_cons_003;
    }
}
